import{c as d,Q as a,j as r,m as e}from"./chunks/framework.B2dUnTNU.js";const u=JSON.parse('{"title":"⚔️ 武器与战斗","description":"","frontmatter":{},"headers":[],"relativePath":"combat/index.md","filePath":"combat/index.md","lastUpdated":1778834375000}'),i={name:"combat/index.md"};function l(h,t,o,n,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="⚔️-武器与战斗" tabindex="-1">⚔️ 武器与战斗 <a class="header-anchor" href="#⚔️-武器与战斗" aria-label="Permalink to &quot;⚔️ 武器与战斗&quot;">​</a></h1><h2 id="🗡️-近战武器对比" tabindex="-1">🗡️ 近战武器对比 <a class="header-anchor" href="#🗡️-近战武器对比" aria-label="Permalink to &quot;🗡️ 近战武器对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>武器</th><th>伤害</th><th>最小伤害</th><th>耐久</th><th>暴击</th><th>攻速</th><th>重量</th><th>入手难度</th></tr></thead><tbody><tr><td>🥇 撬棍 (Crowbar)</td><td>0.9-1.5</td><td>0.1</td><td>70</td><td>20%</td><td>1.0</td><td>2.0</td><td>易</td></tr><tr><td>🥈 消防斧 (Fire Axe)</td><td>1.2-2.5</td><td>0.5</td><td>20</td><td>35%</td><td>0.9</td><td>3.0</td><td>中</td></tr><tr><td>🥉 武士刀 (Katana)</td><td>1.5-3.0</td><td>0.5</td><td>5</td><td>50%</td><td>1.2</td><td>2.0</td><td>极罕见</td></tr><tr><td>棒球棍 (Baseball Bat)</td><td>0.8-1.5</td><td>0.1</td><td>20</td><td>25%</td><td>1.0</td><td>2.0</td><td>易</td></tr><tr><td>铁管 (Metal Pipe)</td><td>0.7-1.3</td><td>0.1</td><td>40</td><td>15%</td><td>1.1</td><td>1.5</td><td>易</td></tr><tr><td>锤子 (Hammer)</td><td>0.5-1.0</td><td>0.1</td><td>30</td><td>20%</td><td>1.1</td><td>1.0</td><td>到处都是</td></tr><tr><td>斧头 (Hand Axe)</td><td>1.0-2.0</td><td>0.3</td><td>15</td><td>35%</td><td>1.0</td><td>2.0</td><td>中</td></tr><tr><td>手工矛 (Crafted Spear)</td><td>0.8-1.5</td><td>0.1</td><td>5</td><td>20%</td><td>0.9</td><td>1.7</td><td>无限自制</td></tr><tr><td>猎刀 (Hunting Knife)</td><td>0.6-1.2</td><td>0.1</td><td>20</td><td>35%</td><td>1.4</td><td>0.5</td><td>中</td></tr><tr><td>螺丝刀 (Screwdriver)</td><td>0.4-0.9</td><td>0.1</td><td>25</td><td>15%</td><td>1.5</td><td>0.4</td><td>到处</td></tr></tbody></table><h2 id="🔫-枪械" tabindex="-1">🔫 枪械 <a class="header-anchor" href="#🔫-枪械" aria-label="Permalink to &quot;🔫 枪械&quot;">​</a></h2><table tabindex="0"><thead><tr><th>武器</th><th>子弹</th><th>伤害</th><th>射程</th><th>噪音半径</th><th>容量</th></tr></thead><tbody><tr><td>M9 手枪</td><td>9mm</td><td>1.0</td><td>8</td><td>50</td><td>15</td></tr><tr><td>M1911 手枪</td><td>.45</td><td>1.2</td><td>8</td><td>70</td><td>7</td></tr><tr><td>左轮 (M625 Revolver)</td><td>.45</td><td>1.2</td><td>8</td><td>70</td><td>6</td></tr><tr><td>沙漠之鹰 (Desert Eagle)</td><td>.44 Magnum</td><td>1.5</td><td>10</td><td>120</td><td>8</td></tr><tr><td>MSR700 猎枪</td><td>.223</td><td>1.5</td><td>12</td><td>100</td><td>3</td></tr><tr><td>JS-2000 散弹枪</td><td>散弹</td><td>2.0</td><td>7</td><td>250</td><td>6</td></tr><tr><td>双管猎枪 (Double Barrel)</td><td>散弹</td><td>2.5</td><td>5</td><td>300</td><td>2</td></tr><tr><td>M14 步枪</td><td>.308</td><td>2.0</td><td>13</td><td>150</td><td>20</td></tr><tr><td>M16 突击步枪</td><td>5.56mm</td><td>1.2</td><td>12</td><td>100</td><td>30</td></tr></tbody></table><h2 id="🧟-僵尸类型" tabindex="-1">🧟 僵尸类型 <a class="header-anchor" href="#🧟-僵尸类型" aria-label="Permalink to &quot;🧟 僵尸类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>速度</th><th>感官</th><th>血量</th><th>行为特征</th></tr></thead><tbody><tr><td>Shamblers (缓行者)</td><td>慢</td><td>标准</td><td>标准</td><td>默认僵尸，大部分是这种</td></tr><tr><td>Fast Shamblers (快步者)</td><td>中</td><td>标准</td><td>标准</td><td>比缓行者快，更危险</td></tr><tr><td>Sprinters (疾跑者)</td><td>极快</td><td>标准</td><td>标准</td><td>沙盒选项可开启，会冲刺追逐</td></tr><tr><td>Crawlers (爬行者)</td><td>极慢</td><td>低</td><td>标准</td><td>趴地爬行，容易漏掉被咬脚</td></tr></tbody></table><h2 id="⚡-战斗技巧" tabindex="-1">⚡ 战斗技巧 <a class="header-anchor" href="#⚡-战斗技巧" aria-label="Permalink to &quot;⚡ 战斗技巧&quot;">​</a></h2><h3 id="走位基础" tabindex="-1">走位基础 <a class="header-anchor" href="#走位基础" aria-label="Permalink to &quot;走位基础&quot;">​</a></h3><ul><li><strong>永远不要后退直走</strong> — 转身跑一段再回头打，拉开距离</li><li><strong>推倒再补刀</strong> — 空格推开僵尸 → 倒地后对头踩（伤害翻倍）</li><li><strong>门框绞肉机</strong> — 在门口打可以同时只面对一只</li><li><strong>围栏陷阱</strong> — 僵尸翻围栏时会摔倒，趁它倒地踩头</li></ul><h3 id="风筝战术-kiting" tabindex="-1">风筝战术（Kiting） <a class="header-anchor" href="#风筝战术-kiting" aria-label="Permalink to &quot;风筝战术（Kiting）&quot;">​</a></h3><ul><li>潜行姿态吸引 1-3 只 → 走 5 步回头打 → 再走 5 步 → 重复</li><li>围栏风筝：绕围栏走，僵尸翻栏时摔倒逐个处理</li><li>窗口风筝：进出建筑窗口，僵尸翻窗速度极慢</li></ul><h3 id="枪械使用时机" tabindex="-1">枪械使用时机 <a class="header-anchor" href="#枪械使用时机" aria-label="Permalink to &quot;枪械使用时机&quot;">​</a></h3><ul><li>🚫 <strong>不要在城镇里开枪</strong> — 枪声会拉来整个街区的僵尸</li><li>✅ <strong>开阔野外</strong> — 有逃跑空间，打不过可以跑</li><li>✅ <strong>配合散弹枪</strong> — JS-2000 散弹一枪能打死多只，适合快速清理</li><li>✅ <strong>退伍兵 + 镇定剂 (Beta Blocker)</strong> — 消除恐慌，提高精准度</li></ul><h3 id="疲劳管理" tabindex="-1">疲劳管理 <a class="header-anchor" href="#疲劳管理" aria-label="Permalink to &quot;疲劳管理&quot;">​</a></h3><ul><li>耐力耗尽时伤害减半，跑步不能</li><li>咬紧牙关时不要恋战，永远留 25% 耐力逃跑</li><li>坐地上/坐椅子上可以快速恢复耐力</li><li>体格 Fitness 等级提高耐力恢复速度</li></ul><div class="danger custom-block"><p class="custom-block-title">被咬 = 100% 死亡</p><p>B41 默认设定：<strong>咬伤 (Bite) = 100% 感染僵尸病毒 = 3 天内必死</strong>。没有被咬的唯一办法是不被咬。抓伤 (Scratch) 有 7% 感染率，撕裂伤 (Laceration) 有 25% 感染率。Thick Skinned 特性可显著降低被抓/咬的概率。</p></div>',17)])])}const m=d(i,[["render",l]]);export{u as __pageData,m as default};
